@main.command()
@click.argument("command", nargs=-1, required=True)
def passthrough(command):
    """Run command without any filtering (escape hatch)."""
    cmd = list(command)
    output, exit_code = run(cmd)
    click.echo(output, nl=False)
    sys.exit(exit_code)


