    """Get a config value by dotted key (e.g. filters.cat.max_lines)."""
    from pytk.config import load_config
    cfg = load_config()
    parts = key.split(".")
    val = cfg
    for p in parts:
        if not isinstance(val, dict) or p not in val:
            click.echo(f"Key not found: {key}", err=True)
            raise SystemExit(1)
        val = val[p]
    click.echo(str(val))


